//! ⚠️ Numeric provenance projects exact original diagnostic fragments without collecting IDs.
use crate::LayoutMutation;
use semio_s_artifact_layout_layout_model::{Frame,snapshot::LayoutSnapshot};
use semio_framework_value::retained_clone::RetainedCloneRef;
use semio_framework_diagnostic::Severity;
use super::{batch_message::{DynamicMessageSource,MessagePiece},batch_plan::{FrameSelectionPlan,BatchFailure}};
fn input(m:&LayoutMutation)->(&String,&Vec<String>){match m{LayoutMutation::DragFrames(p)=>(&p.page_id,&p.targets),LayoutMutation::RotateFrames(p)=>(&p.page_id,&p.targets),LayoutMutation::ScaleFrames(p)=>(&p.page_id,&p.targets),_=>unreachable!("original batch source")}}
fn page<'a>(m:RetainedCloneRef<'a,LayoutMutation>)->RetainedCloneRef<'a,String>{m.project(7600,|m|input(m).0)}
fn target<'a>(m:RetainedCloneRef<'a,LayoutMutation>,i:usize)->RetainedCloneRef<'a,String>{m.project(7601,|m|input(m).1).project(i,move|rows|&rows[i])}
fn frame<'a>(b:RetainedCloneRef<'a,LayoutSnapshot>,page:usize,i:usize)->RetainedCloneRef<'a,String>{b.project(9,|b|&b.pages).project(page,move|rows|&rows[page]).project(2,|p|&p.frames).project(i,move|rows|&rows[i]).project(0,|f|match f{Frame::Rect{id,..}|Frame::Text{id,..}|Frame::Image{id,..}=>id})}
#[derive(Clone,Copy)]pub enum DiagnosticKind{Failure,Missing,Locked,Noop}
pub fn count(plan:&FrameSelectionPlan)->usize{if plan.failure.is_some(){1}else{usize::from(!plan.missing().is_empty())+usize::from(!plan.locked().is_empty())+usize::from(plan.changed().is_empty())}}
pub fn kind(plan:&FrameSelectionPlan,index:usize)->DiagnosticKind{if plan.failure.is_some(){return DiagnosticKind::Failure}let missing=usize::from(!plan.missing().is_empty());if index<missing{return DiagnosticKind::Missing}let locked=usize::from(!plan.locked().is_empty());if index<missing+locked{return DiagnosticKind::Locked}DiagnosticKind::Noop}
pub struct BatchDiagnosticSource<'a>{pub m:RetainedCloneRef<'a,LayoutMutation>,pub b:RetainedCloneRef<'a,LayoutSnapshot>,pub plan:&'a FrameSelectionPlan,pub index:usize}
impl BatchDiagnosticSource<'_>{fn kind(&self)->DiagnosticKind{kind(self.plan,self.index)}fn group(&self)->&[usize]{match self.kind(){DiagnosticKind::Missing=>self.plan.missing(),DiagnosticKind::Locked=>self.plan.locked(),_=>&[]}}fn group_id(&self,index:usize)->RetainedCloneRef<'_,String>{match self.kind(){DiagnosticKind::Missing=>target(self.m,self.group()[index]),DiagnosticKind::Locked=>frame(self.b,self.plan.page,self.group()[index]),_=>unreachable!("diagnostic group provenance")}}}
impl DynamicMessageSource for BatchDiagnosticSource<'_>{
 fn mutation(&self)->RetainedCloneRef<'_,LayoutMutation>{self.m}fn baseline(&self)->RetainedCloneRef<'_,LayoutSnapshot>{self.b}fn identity(&self)->usize{7700+self.index}
 fn level(&self)->Severity{match self.kind(){DiagnosticKind::Failure=>if matches!(self.plan.failure,Some(BatchFailure::PageMissing|BatchFailure::NoneUnlocked)){Severity::Error}else{Severity::Fatal},_=>Severity::Warning}}
 fn code(&self)->&'static str{match self.kind(){DiagnosticKind::Failure=>if matches!(self.plan.failure,Some(BatchFailure::PageMissing|BatchFailure::NoneUnlocked)){"mutation.target-missing"}else{"mutation.invariant"},DiagnosticKind::Noop=>"mutation.no-op",_=>"mutation.partial"}}
 fn piece_count(&self)->usize{match self.kind(){DiagnosticKind::Missing|DiagnosticKind::Locked=>3+self.group().len()*2,DiagnosticKind::Noop=>1,DiagnosticKind::Failure=>match self.plan.failure.unwrap(){BatchFailure::Duplicate=>3,BatchFailure::PageMissing=>3,BatchFailure::NoneUnlocked=>5,_=>1}}}
 fn piece(&self,index:usize)->MessagePiece<'_>{use MessagePiece::*;match self.kind(){DiagnosticKind::Missing|DiagnosticKind::Locked=>match index{0=>Unsigned(self.group().len()),1=>Literal(" of "),2=>Unsigned(input(self.m.get()).1.len()),3=>Literal(if matches!(self.kind(),DiagnosticKind::Missing){" target(s) skipped (not on this page): "}else{" target(s) skipped (locked): "}),i=>if i%2==0{Original(self.group_id((i-4)/2))}else{Literal(", ")}},DiagnosticKind::Noop=>Literal("The transform moves no frame."),DiagnosticKind::Failure=>match self.plan.failure.unwrap(){BatchFailure::Envelope=>Literal(match self.m.get(){LayoutMutation::DragFrames(_)=>"A drag offset must be finite.",LayoutMutation::RotateFrames(_)=>"A turn's pivot and angle must be finite.",_=>"A scaling's pivot must be finite and its factors finite and positive."}),BatchFailure::Empty=>Literal("targets must name at least one frame"),BatchFailure::Duplicate=>match index{0=>Literal("targets must not repeat \""),1=>EscapedOriginal(target(self.m,self.plan.duplicate.unwrap())),_=>Literal("\"")},BatchFailure::PageMissing=>match index{0=>Literal("Page \""),1=>Original(page(self.m)),_=>Literal("\" does not exist.")},BatchFailure::NoneUnlocked=>match index{0=>Literal("None of the "),1=>Unsigned(input(self.m.get()).1.len()),2=>Literal(" target(s) is an unlocked frame of page \""),3=>Original(page(self.m)),_=>Literal("\".")},BatchFailure::Bounds=>Literal("Frame bounds must be finite and have a positive size.")}}}
 fn target_count(&self)->usize{match self.kind(){DiagnosticKind::Missing|DiagnosticKind::Locked=>self.group().len(),DiagnosticKind::Failure if self.plan.failure==Some(BatchFailure::PageMissing)=>1,_=>input(self.m.get()).1.len()}}
 fn target(&self,index:usize)->RetainedCloneRef<'_,String>{match self.kind(){DiagnosticKind::Missing|DiagnosticKind::Locked=>self.group_id(index),DiagnosticKind::Failure if self.plan.failure==Some(BatchFailure::PageMissing)=>page(self.m),_=>target(self.m,index)}}
}
